boolean remove(int x) {
    Integer i = pos.get(x);
    if (i == null) return false;
    int last = a.get(a.size() - 1);
    a.set(i, last);            // move last element into the hole
    pos.put(last, i);
    a.remove(a.size() - 1);    // Θ(1): removing the last slot
    pos.remove(x);             // after pos.put, in case x == last
    return true;
}
